const $ = s => document.querySelector(s);
const escapeHTML = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const E = escapeHTML;
const products = {'theme-center':'主题中心',packer:'打包器',operations:'影视中心〔APP 后台〕',client:'APP 客户端'};
const kinds = {software:'软件更新','product-source':'产品源码','client-source':'客户端源码',theme:'主题模板',installer:'成品安装包'};
const pages = {overview:'工作台',products:'产品中心',productTheme:'主题中心',productPacker:'打包器',productOperations:'影视中心',terminalUpdates:'终端更新',customers:'授权中心',bindings:'设备与站点',releases:'版本中心',updatePushes:'更新推送',announcements:'公告中心',jobs:'云端打包',nodes:'打包节点',integrations:'产品对接',deployment:'部署与迁移',audit:'操作记录',settings:'终端设置'};
const states = {active:'启用',disabled:'已停用',published:'已发布',withdrawn:'已下架',draft:'草稿',queued:'等待节点',running:'构建中',complete:'已完成',failed:'失败',cancelled:'已取消',expired:'已到期'};
let csrf = '', data = null, page = pages[location.hash.slice(1)] ? location.hash.slice(1) : 'overview', releaseTab = 'software', releaseProduct='packer', releaseView='resources', lastRefresh = null;
const date = v => v ? new Date(v).toLocaleString('zh-CN',{hour12:false}) : '未报告';
const size = v => v < 1048576 ? (v / 1024).toFixed(1)+' KB' : (v/1048576).toFixed(1)+' MB';
const badge = status => `<span class="badge ${E(status)}">${E(states[status] || status)}</span>`;
const customer = id => data.customers.find(c=>c.id===id)?.name || '未知客户';
const licenseName = id => {const l=data.licenses.find(l=>l.id===id);return l?authorizationLabel(l):'管理员';};
const button = (action, label, id='', cls='') => `<button class="button small ${cls}" data-action="${action}" data-id="${E(id)}">${label}</button>`;
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,4500);}
async function api(url, method='GET', body, extra={}) {
  const headers = {...extra}; if(method!=='GET') headers['X-CSRF-Token']=csrf;
  if(body && !(body instanceof File) && !(body instanceof Blob)) {headers['Content-Type']='application/json';body=JSON.stringify(body);}
  const res=await fetch(url,{method,headers,body,credentials:'same-origin'});
  const json=await res.json(); if(!res.ok){if(res.status===401 && url!=='/api/login') showLogin();throw Error(json.error || '请求失败');} return json;
}
function showLogin(){closeAccountMenu();csrf='';data=null;$('#shell').hidden=true;$('#login').hidden=false;if($('#modal').open)$('#modal').close();}
function showShell(){$('#login').hidden=true;$('#shell').hidden=false;}
function setTheme(theme){document.documentElement.dataset.theme=theme;localStorage.setItem('puffer-terminal-theme',theme);document.querySelectorAll('.theme-toggle').forEach(b=>{b.textContent=theme==='dark'?'☀':'☾';b.setAttribute('aria-label',theme==='dark'?'切换日间模式':'切换夜间模式');});}
setTheme(localStorage.getItem('puffer-terminal-theme')==='dark'?'dark':'light');
document.querySelectorAll('.theme-toggle').forEach(b=>b.addEventListener('click',()=>setTheme(document.documentElement.dataset.theme==='dark'?'light':'dark')));
$('#menu-toggle').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));
function closeAccountMenu(){ $('#account-menu').hidden=true; $('#account-menu-toggle').setAttribute('aria-expanded','false'); }
function toggleAccountMenu(){const menu=$('#account-menu');menu.hidden=!menu.hidden;$('#account-menu-toggle').setAttribute('aria-expanded',String(!menu.hidden));if(!menu.hidden)menu.querySelector('button').focus();}
function userCenter(){if(!data)return;closeAccountMenu();openModal('用户中心',`<div class="user-profile"><span class="admin-avatar">A</span><div><h3>管理员</h3><p class="muted">admin · 终端管理员</p></div></div><div class="stat-line"><span>登录账号</span><strong>admin</strong></div><div class="stat-line"><span>终端版本</span><strong>v${E(data.version)}</strong></div><div class="form-actions"><button id="user-password" class="button primary">修改密码</button><button id="user-logout" class="button">退出登录</button></div>`);$('#user-password').addEventListener('click',()=>passwordModal());$('#user-logout').addEventListener('click',()=>$('#logout').click());}
$('#user-center').addEventListener('click',userCenter);
$('#account-center-menu').addEventListener('click',userCenter);
$('#account-menu-toggle').addEventListener('click',toggleAccountMenu);
$('.account-control').addEventListener('contextmenu',e=>{e.preventDefault();if($('#account-menu').hidden)toggleAccountMenu();});
document.addEventListener('click',e=>{if(!e.target.closest('.account-control'))closeAccountMenu();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#account-menu').hidden){closeAccountMenu();$('#user-center').focus();}});
$('#logout').addEventListener('click',async()=>{try{await api('/api/logout','POST',{});showLogin();}catch(e){toast(e.message);}});
$('#refresh').addEventListener('click',()=>refresh().catch(e=>toast(e.message)));
$('#login-form').addEventListener('submit',async e=>{e.preventDefault();const form=e.target,submit=form.querySelector('button[type=submit]');submit.disabled=true;$('#login-error').textContent='';try{const values=Object.fromEntries(new FormData(form));const result=await api('/api/login','POST',values);csrf=result.csrf;form.elements.password.value='';if(result.mustChange)passwordModal(true);else {showShell();await refresh();}}catch(err){$('#login-error').textContent=err.message;}finally{submit.disabled=false;}});
$('#modal-close').addEventListener('click',()=>$('#modal').close());
$('#modal').addEventListener('close',()=>{if(!$('#modal').open)$('#modal-body').replaceChildren();});
window.addEventListener('hashchange',()=>{page=pages[location.hash.slice(1)]?location.hash.slice(1):'overview';$('#sidebar').classList.remove('open');if(data)render();});
function openModal(title,html,forced=false){const modal=$('#modal');if(modal.open)modal.close();$('#modal-title').textContent=title;$('#modal-body').innerHTML=html;$('#modal-close').hidden=forced;modal.oncancel=forced?e=>e.preventDefault():null;modal.showModal();const first=$('#modal-body input');if(first)first.focus();}
function formModal(title,fields,submit,after,forced=false){openModal(title,`<form id="dialog-form">${fields}<p class="error" id="form-error" role="alert"></p><div class="form-actions"><button class="button primary" type="submit">${submit}</button></div></form>`,forced);$('#dialog-form').addEventListener('submit',async e=>{e.preventDefault();const f=e.target,b=f.querySelector('button[type=submit]');b.disabled=true;$('#form-error').textContent='';try{const values=Object.fromEntries(new FormData(f));await after(values,f);}catch(err){if($('#form-error'))$('#form-error').textContent=err.message;else toast(err.message);}finally{b.disabled=false;}});}
const field=(name,title,type='text',value='',extra='')=>`<label>${title}<input name="${name}" type="${type}" value="${E(value)}" ${extra}></label>`;
const select=(name,title,entries,selected='')=>`<label>${title}<select name="${name}">${entries.map(([v,t])=>`<option value="${E(v)}" ${v===selected?'selected':''}>${E(t)}</option>`).join('')}</select></label>`;
const check=(name,title,on=true)=>`<label class="check-label"><input type="checkbox" name="${name}" ${on?'checked':''}>${title}</label>`;
function passwordModal(forced=false){formModal(forced?'设置管理员密码':'修改管理员密码',`<p class="section-note">${forced?'首次登录需要设置自己的密码。':'修改后，其他登录会话将退出。'}</p>${field('current','当前密码','password','','required autocomplete="current-password"')}${field('password','新密码','password','','required autocomplete="new-password"')}${field('confirm','确认新密码','password','','required autocomplete="new-password"')}`,'保存密码',async v=>{if(v.password!==v.confirm)throw Error('两次输入的新密码不一致');await api('/api/password','POST',{current:v.current,password:v.password});$('#modal').close();showShell();await refresh();toast('密码已修改');},forced);}
async function refresh(){if(!csrf)return;$('#refresh-state').textContent='正在刷新';data=await api('/api/overview');data.integration=await api('/api/integrations');data.selfUpdate=await api('/api/self-update');data.migration=await api('/api/migration/status');lastRefresh=new Date();$('#refresh-state').textContent='更新于 '+lastRefresh.toLocaleTimeString('zh-CN',{hour12:false});$('#service-version').textContent='终端 v'+data.version;page=pages[location.hash.slice(1)]?location.hash.slice(1):'overview';render();}
function heading(title,description,action=''){return `<div class="page-heading"><div><div class="eyebrow">PUFFER / ${E(page.toUpperCase())}</div><h1>${title}</h1><p>${description}</p></div>${action}</div>`;}
function panel(title,subtitle,body,action=''){return `<section class="panel"><div class="panel-head"><div><h3>${title}</h3>${subtitle?`<p>${subtitle}</p>`:''}</div>${action}</div><div class="panel-body">${body}</div></section>`;}
function empty(title,description,action=''){return `<div class="empty"><div class="empty-icon">◇</div><strong>${title}</strong><p>${description}</p>${action}</div>`;}
function table(headers,rows,className=''){return `<div class="table-wrap ${className}"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`;}
function overview(){const s=data,valid=s.licenses.filter(l=>l.status==='active'&&Date.parse(l.expiresAt)>Date.now());const online=s.nodes.filter(n=>n.status==='active'&&Date.parse(n.lastSeenAt)>Date.now()-300000);return heading('工作空间总览','每一个产品、授权与版本，都在这里连接。',`<button class="button primary" data-action="issue">＋ 新增授权</button>`)+`<div class="metrics">${[['授权总数',s.licenses.length,'已签发的 Key 授权','♧'],['有效授权',valid.length,'一个 Key 连接三个产品','⌘'],['已发布版本',s.releases.filter(r=>r.status==='published').length,'软件、源码、主题与成品','◫'],['等待构建',s.jobs.filter(j=>j.status==='queued').length,online.length+' 个打包节点在线','◇']].map(([t,n,d,i])=>`<div class="metric"><div class="metric-header"><span>${t}</span><span class="metric-icon">${i}</span></div><div class="metric-number">${n}</div><div class="metric-note">${d}</div></div>`).join('')}</div><div class="two-column"><div>${panel('三个产品，一个终端','各自迭代，统一授权与版本分发',`<div class="product-grid">${Object.entries(products).filter(([p])=>p!=='client').map(([p,t],i)=>{const rel=s.releases.filter(r=>r.kind==='software'&&r.product===p&&r.status==='published');return `<a class="product-card" href="#${workspaceRoutes[p]}"><div class="product-symbol">${['◈','◇','▣'][i]}</div><h3>${t}</h3><p>${['主题创作、模板与视觉装饰','源码版本、主题组合与应用交付','站点管理、内容与功能运营'][i]}</p><div class="product-bottom"><strong>${rel.length}</strong> 个已发布版本</div></a>`;}).join('')}</div><div class="flow"><strong>新增授权</strong><span>→</span><strong>激活产品</strong><span>→</span><strong>发布更新</strong></div>`,`<a href="#products">进入产品中心 ↗</a>`)}${panel('最近交付','最新的真实云端打包',s.jobs.length?table(['应用 / 目标','创建时间','状态'],s.jobs.slice(0,4).map(j=>`<tr><td><span class="table-title">${E(j.app.name)}</span><div class="sub">${E(j.target)} · ${E(j.app.version)}</div></td><td>${date(j.createdAt)}</td><td>${badge(j.status)}</td></tr>`)):empty('还没有云端打包','发布客户端源码和主题后，即可创建云端打包。',button('build','创建任务')),`<a href="#jobs">查看全部 ↗</a>`)}</div><div>${panel('授权策略','首次联网激活，随后定期校验',`<div class="stat-line"><span>离线有效期</span><strong>72 小时（在线）</strong></div><div class="stat-line"><span>建议校验周期</span><strong>60 秒（在线）</strong></div><div class="stat-line"><span>激活设备 / 站点</span><strong>${s.bindings.filter(b=>b.status==='active').length}</strong></div><div class="stat-line"><span>在线打包节点</span><strong>${online.length} / ${s.nodes.length}</strong></div><p class="section-note">授权停用后，联网请求立即拒绝；已签发的离线凭据在到期后失效。</p>`)}${panel('最近操作','保留关键操作记录',s.audit.length?`<div class="stack">${s.audit.slice(0,5).map(a=>`<div class="stat-line"><span>${E(a.action)}</span><small>${date(a.at).slice(5)}</small></div>`).join('')}</div>`:empty('暂无操作记录','开始配置终端后自动记录。'))}</div></div>`;}
function authorizationLabel(l){return !l.label||l.label==='三产品授权'||l.label==='统一产品授权'?customer(l.customerId):l.label;}
function licenseProducts(l){return ['theme-center','packer','operations'].map(p=>'<span class="badge '+(l.products.includes(p)?'active':'license-off')+'">'+E(products[p])+(l.products.includes(p)?'':' · 未开通')+'</span>').join(' ');}
function customers(){
 const rows=data.licenses.map(l=>'<tr><td><strong>'+E(authorizationLabel(l))+'</strong><div class="sub">Key 编号 '+E(l.id.slice(0,8))+'</div></td><td>'+E((l.domains||[]).join('、')||'不限域名')+'</td><td>'+licenseProducts(l)+'</td><td>'+date(l.expiresAt)+'</td><td>'+badge(l.status==='active'&&Date.parse(l.expiresAt)<=Date.now()?'expired':l.status)+'</td><td><div class="actions">'+button('license-manage','编辑',l.id,'primary')+button('license-more','更多',l.id)+button('license-delete','删除',l.id,'danger')+'</div></td></tr>');
 return heading('授权中心','填写名字和域名，一个 Key 管理主题中心、打包器和影视中心。',button('issue','＋ 新增授权','','primary'))+'<section class="panel"><div class="toolbar"><strong>授权列表</strong><input id="table-filter" class="inline-filter" placeholder="搜索名字、域名或 Key 编号" aria-label="搜索授权"></div>'+(rows.length?table(['名字','授权域名','授权产品','有效期','状态','操作'],rows):empty('暂无授权','填写名字、域名和有效期，保存后生成 Key。',button('issue','新增授权')))+'</section>'+packagePanel()+'<details class="panel license-section"><summary>高级授权设置</summary>'+policyPanel()+'</details>';
}
function licenseProductFields(l){return '<div class="license-access-grid">'+['theme-center','packer','operations'].map(p=>'<div class="license-access-card">'+check('product-'+p,products[p],l.products.includes(p))+'<p class="field-help">'+({'theme-center':'主题制作与模板资源',packer:'源码下载与应用打包',operations:'APP 后台与域名站点'}[p])+'</p>'+field('quota-'+p,p==='operations'?'站点名额':'设备名额','number',l.quotas[p],'required min="1" max="100"')+'</div>').join('')+'</div>';}
function licenseManage(id){const l=data.licenses.find(x=>x.id===id);formModal('编辑授权 · '+authorizationLabel(l),field('label','名字','text',authorizationLabel(l),'required maxlength="80"')+'<label>授权域名（一行一个，可添加或删除）<textarea name="domains" rows="3">'+E((l.domains||[]).join('\n'))+'</textarea></label>'+field('expiresAt','有效期','date',l.expiresAt.slice(0,10),'required')+'<h3>授权产品</h3>'+['theme-center','packer','operations'].map(p=>check('product-'+p,products[p],l.products.includes(p))).join('')+'<details class="license-section"><summary>高级设置：设备名额、运行模式和权限</summary>'+['theme-center','packer','operations'].map(p=>field('quota-'+p,products[p]+'名额','number',l.quotas[p],'required min="1" max="100"')).join('')+select('authorizationMode','运行模式',[['','跟随全局'],['online','在线管理'],['silent-local','静默本地']],l.authorizationMode||'')+['sourceDownload','localBuild','cloudBuild'].map(k=>check(k,{sourceDownload:'允许下载源码',localBuild:'允许本地打包',cloudBuild:'允许云端打包'}[k],l.permissions[k])).join('')+'</details><p class="field-help">留空域名表示不限制域名。设备、IP、地区和激活记录可在“更多 → 本 Key 日志中心”查看。</p>','保存',async(v,f)=>{const ps=['theme-center','packer','operations'].filter(p=>f.elements['product-'+p].checked);if(!ps.length)throw Error('至少开通一个产品');const payload={label:v.label,products:ps,domains:v.domains.split(/[\n,，]/).map(x=>x.trim()).filter(Boolean),quotas:Object.fromEntries(['theme-center','packer','operations'].map(p=>[p,Number(v['quota-'+p])])),authorizationMode:v.authorizationMode||null,permissions:Object.fromEntries(['sourceDownload','localBuild','cloudBuild'].map(p=>[p,f.elements[p].checked]))};if(v.expiresAt!==l.expiresAt.slice(0,10))payload.expiresAt=new Date(v.expiresAt+'T23:59:59').toISOString();await api('/api/licenses/'+id,'PATCH',payload);$('#modal').close();await refresh();toast('授权已保存，Key 保持不变');});}
function licenseMore(id){const l=data.licenses.find(x=>x.id===id);openModal('授权操作 · '+authorizationLabel(l),'<p class="section-note">以下操作作用于同一个 Key 的全部授权产品。仅关闭某个产品，请进入“管理授权”取消对应勾选。</p><div class="license-more-actions">'+button('authorization-logs','本 Key 日志中心',id)+button('renew','续期全部产品',id)+button('license-toggle',l.status==='active'?'停用整个 Key':'启用整个 Key',id)+button('rotate','更换 Key',id)+button('license-delete','删除授权',id,'danger')+'</div>');}
function policyPanel(){const s=data.settings,inherited=data.licenses.filter(l=>!l.authorizationMode);const pending=data.bindings.filter(b=>{const l=data.licenses.find(x=>x.id===b.licenseId);return l&&b.policyRevision!==String(s.policyRevision||1)+'.'+String(l.policyRevision||1);});return panel('授权运行模式','全局默认 · '+modeName(s.authorizationMode),'<div class="policy-grid"><div><strong>'+modeName(s.authorizationMode)+'</strong><p>两个模式每次启动均询问终端。在线断网最多宽限72小时；静默按许可本地运行，每隔 '+s.reconnectHours+' 小时尝试重连。</p></div><div><strong>'+inherited.length+' 份跟随全局</strong><p>'+pending.length+' 个绑定等待获取当前策略。已离线产品在下一次成功连接后生效。</p></div></div><p class="field-help">单独设置客户策略可覆盖全局。域名、Key 和设备身份仍保留；收到可信撤销立即锁定；无法联网不等于被撤销。在线另有60秒轮询，静默在重连后接收撤销。</p>',button('authorization-logs','全部授权日志')+button('policy-distribution','策略回执')+button('global-policy','修改全局模式'));}
function globalPolicy(){formModal('全局授权模式',select('authorizationMode','运行模式',[['online','在线管理'],['silent-local','静默本地']],data.settings.authorizationMode)+field('reconnectHours','静默重连间隔（小时）','number',data.settings.reconnectHours,'min="1" max="168" required')+'<p class="section-note">仅影响跟随全局的授权。已有产品下次联网取得签名策略后生效。</p>','保存策略',async v=>{await api('/api/authorization-policy','PATCH',{...v,reconnectHours:Number(v.reconnectHours)});$('#modal').close();await refresh();});}
function licensePolicy(id){const l=data.licenses.find(x=>x.id===id);formModal('客户授权策略 · '+customer(l.customerId),select('authorizationMode','运行模式',[['','跟随全局'],['online','在线管理'],['silent-local','静默本地']],l.authorizationMode||'')+'<label>授权影视后台域名（一行一个）<textarea name="domains" rows="3" placeholder="film.example.com">'+E((l.domains||[]).join('\n'))+'</textarea></label><p class="field-help">限制域名后，三个产品激活需提供匹配域名。桌面产品还绑定设备。留空保持现有设备/站点名额策略。</p>'+['sourceDownload','localBuild','cloudBuild'].map(k=>check(k,{sourceDownload:'允许下载产品与 APP 源码',localBuild:'允许本地打包',cloudBuild:'允许云端打包'}[k],l.permissions[k])).join(''),'保存客户策略',async(v,form)=>{await api('/api/licenses/'+id,'PATCH',{authorizationMode:v.authorizationMode||null,domains:v.domains.split(/[\n,，]/).map(x=>x.trim()).filter(Boolean),permissions:Object.fromEntries(['sourceDownload','localBuild','cloudBuild'].map(k=>[k,form.elements[k].checked]))});$('#modal').close();await refresh();});}
function repositoryConfig(){const c=data.repositories?.[releaseProduct]||{};formModal('绑定 '+centers[releaseProduct].title+' 仓库',field('repository','GitHub 仓库','text',c.repository||'','placeholder="owner/repo"')+field('branch','检查分支','text',c.branch||'main','required')+'<p class="field-help">可检查公开仓库；留空取消绑定。仓库提交不自动发布给客户。</p>','保存',async v=>{await api('/api/repositories/'+releaseProduct,'PATCH',v);$('#modal').close();await refresh();});}
function bindings(productFilter=''){const bindings=data.bindings.filter(b=>!productFilter||b.product===productFilter);return heading('设备与站点','桌面产品绑定设备，运营中心绑定独立域名。')+`<section class="panel"><div class="toolbar"><h3>已激活的产品</h3><input id="table-filter" class="inline-filter" placeholder="搜索设备、域名或客户" aria-label="搜索绑定"></div>${bindings.length?table(['客户 / 产品','设备或域名','客户端版本','最近联网','状态','操作'],bindings.map(b=>`<tr><td class="table-title">${E(licenseName(b.licenseId))}<div class="sub">${products[b.product]}</div></td><td class="code">${E(b.binding)}<div class="sub">${E(b.label)}</div></td><td>${E(b.version)}<div class="sub">${b.authorizationMode?E(modeName(b.authorizationMode)):'待接入策略'} · ${E(b.policyRevision||'—')}</div></td><td>${date(b.lastSeenAt)}</td><td>${badge(b.status)}</td><td>${button('binding-toggle',b.status==='active'?'停用绑定':'启用绑定',b.id)}</td></tr>`)):empty('等待产品激活','产品通过激活接口上报后，设备与站点会真实显示在这里。')}</section>`;}
const centers={packer:{title:'打包器',icon:'◇',text:'客户端源码 + 主题模板，生成应用安装包',types:['software','installer','product-source']},'theme-center':{title:'主题中心',icon:'◈',text:'主题设计、装饰与模板制作，独立软件迭代',types:['software','installer','product-source']},operations:{title:'影视中心〔APP 后台〕',icon:'▣',text:'对接苹果 CMS，管理 APP 内容与运营功能',types:['software','installer','product-source']},client:{title:'APP 客户端资源',icon:'▶',text:'可构建的 Flutter / uni-app 源码和成品 APP',types:['client-source','installer']},templates:{title:'主题模板',icon:'◫',text:'发布后供主题中心和打包器查询、安装',types:['theme']},terminal:{title:'河豚终端',icon:'⌘',text:'授权与版本分发服务自身的 Git 在线更新',types:[]}};
const modeName=m=>m==='silent-local'?'静默本地':'在线管理';
const effectiveMode=l=>l.authorizationMode||data.settings.authorizationMode||'online';
function repositoryPanel(){const c=data.repositories?.[releaseProduct]||{};return panel('Git 来源',c.repository?c.repository+' · '+c.branch:'尚未绑定仓库', '<div class="repo-summary"><span>'+ (c.latestCommit?'<span class="code">'+E(c.latestCommit.sha.slice(0,12))+'</span> · '+E(c.latestCommit.message.split('\n')[0]):'检查仓库提交与 Release 附件后，选择需要的文件导入草稿。')+'</span><span class="sub">'+(c.checkedAt?'最近检查 '+date(c.checkedAt):'尚未检查')+'</span></div>'+(c.error?'<p class="error">'+E(c.error)+'</p>':'')+'<p class="field-help">Git 提交更新与可安装版本分别记录。附件导入后经校验进入草稿，由你发布。</p>'+(c.upstream?.length?'<details class="git-assets"><summary>Git Release 附件 · '+c.upstream.length+' 个版本</summary>'+c.upstream.map(r=>'<div class="git-release"><strong>'+E(r.name)+'</strong><span class="badge">'+E(r.tag)+'</span><p class="sub">'+date(r.publishedAt)+'</p>'+r.assets.map(a=>'<div class="asset-row"><span>'+E(a.name)+'<small>'+size(a.bytes)+'</small></span>'+button('git-import','导入草稿',String(a.id))+'</div>').join('')+(r.assets.length?'':'<p class="sub">此版本没有可导入的附件。</p>')+'</div>').join('')+'</details>':'<p class="sub">暂无已检查的 Release 附件，可直接上传产品文件。</p>'),'<div class="actions">'+button('git-config','绑定仓库')+'<button class="button small" data-action="git-check" '+(!c.repository?'disabled':'')+'>检查更新</button></div>');}
function releases(embedded=false){const info=centers[releaseProduct];if(!info.types.includes(releaseTab)&&info.types.length)releaseTab=info.types[0];const rows=data.releases.filter(r=>r.kind===releaseTab&&(releaseProduct==='templates'?r.kind==='theme':r.product===releaseProduct));const menu='<div class="release-products">'+Object.entries(centers).map(([p,v])=>'<button class="release-product '+(releaseProduct===p?'selected':'')+'" data-release-product="'+p+'"><span class="center-icon">'+v.icon+'</span><strong>'+v.title+'</strong><small>'+v.text+'</small></button>').join('')+'</div>';const head=heading('版本中心','独立管理产品、源码与模板，统一发布版本并保留更新记录。',releaseProduct==='terminal'?'':'<button class="button primary" data-action="upload">↑ 上传版本</button>');if(releaseProduct==='terminal')return head+menu+updatePanel();if(['theme-center','packer','operations'].includes(releaseProduct)&&releaseView!=='records')return (embedded?'':heading('版本中心','选择产品，更新发布成品，再选择授权推送。')+menu)+softwareVersions(releaseProduct);const views='<div class="center-views">'+[['resources','版本与资源'],['history','发布历史'],...(!embedded?[['records','产品云端记录']]:[])].map(([v,t])=>'<button class="tab '+(releaseView===v?'active':'')+'" data-release-view="'+v+'">'+t+'</button>').join('')+'</div>';let content='';if(releaseView==='history'){const events=(data.releaseHistory||[]).filter(x=>{const resource=data.releases.find(r=>r.id===x.target);return releaseProduct==='templates'?x.product==='templates'||resource?.kind==='theme':x.product===releaseProduct&&(releaseProduct!=='client'||resource?.kind!=='theme');});content=panel('发布与 Git 历史','保存上传、发布、下架与仓库检查记录',events.length?table(['时间','操作','详情'],events.map(x=>'<tr><td>'+date(x.at)+'</td><td>'+E(x.action)+'</td><td>'+E(x.detail)+'<div class="sub">'+E(x.target)+'</div></td></tr>')):empty('暂无历史','发生发布或仓库操作后自动记录。'));}else if(releaseView==='records'){const records=(data.productRecords||[]).filter(x=>x.product===releaseProduct);content=panel('产品云端记录','产品接入后同步主题导出、模板安装、本地打包和更新结果',records.length?recordTable(records):empty('等待产品上报','终端接口已提供，产品接入并上传真实事件后显示记录。'),button('record-browse','查询全部记录'))+'<p class="field-help">这里只保存事件元数据；文件上传与版本发布独立管理。显示最近收到的记录，完整记录可按客户查询。</p>';}else{content=repositoryPanel()+'<section class="panel"><div class="toolbar"><div class="tabs">'+info.types.map(k=>'<button class="tab '+(releaseTab===k?'active':'')+'" data-release-tab="'+k+'">'+kinds[k]+'</button>').join('')+'</div><input id="table-filter" class="inline-filter" placeholder="搜索版本名称" aria-label="搜索版本"></div>'+(rows.length?table(['版本 / 类型','平台 / 渠道','文件','状态','操作'],rows.map(r=>'<tr><td><span class="table-title">'+E(r.name)+'</span><div class="sub">v'+E(r.version)+' · '+E(kinds[r.kind])+(r.force?' · 强制更新':'')+'</div></td><td>'+E(r.platform)+' / '+E(r.arch)+'<div class="sub">'+E(r.channel)+(r.device?' · '+E(r.device):'')+'</div></td><td>'+size(r.bytes)+'<div class="sub">'+E(r.filename)+'</div></td><td>'+badge(r.status)+'</td><td><div class="actions">'+button('release-detail','详情',r.id)+button(r.status==='published'?'withdraw':'publish',r.status==='published'?'下架':'发布',r.id)+'<a class="button small" href="/api/releases/'+r.id+'/download">下载</a></div></td></tr>')):empty('暂无'+kinds[releaseTab],'上传真实文件或从 Git Release 导入，校验后发布。',button('upload','上传版本')))+'</section><div class="notice subtle">'+(releaseProduct==='templates'?'模板按渲染器与设备类型提供目录；主题中心查询后自行安装，保留用户编辑内容。':releaseProduct==='client'?'APP 源码用于二次打包，Flutter 与 uni-app 主题需匹配；成品安装包可以直接下载安装。':'软件更新 / 安装包为产品成品，产品源码为独立 ZIP 文件；安装说明、升级说明和兼容要求在版本详情中查看。')+'</div>';}return (embedded?'':head+menu)+(embedded&&workspaceTab==='records'?'':views)+content;}
const eventNames={'theme-export':'主题导出','template-install':'模板安装','local-build':'本地打包','source-download':'源码下载','theme-install':'主题安装','update-check':'检查更新','update-success':'更新成功','update-failed':'更新失败'};
function recordTable(records){return table(['客户 / 产品','事件','版本 / 资源','发生 / 收到'],records.map(x=>'<tr><td>'+E(customer(x.customerId))+'<div class="sub">'+E(products[x.product])+'</div></td><td>'+E(eventNames[x.type]||x.type)+'<div class="sub">'+E(x.details?.result||'')+'</div></td><td>'+E(x.version)+'<div class="sub">'+E(x.details?.name||x.details?.message||'')+'</div></td><td>'+date(x.occurredAt)+'<div class="sub">'+date(x.receivedAt)+'</div></td></tr>'));}
function recordBrowse(){openModal('产品云端记录','<div class="field-grid">'+select('recordLicense','客户 / 授权',[['','全部客户'],...data.licenses.map(l=>[l.id,customer(l.customerId)+' · '+l.label])])+select('recordProduct','产品',[['','全部产品'],...Object.entries(products).filter(([p])=>p!=='client')],['packer','theme-center','operations'].includes(releaseProduct)?releaseProduct:'')+'</div><div id="record-results"></div><div class="form-actions"><button class="button" id="record-prev">上一页</button><span id="record-page"></span><button class="button" id="record-next">下一页</button></div>');let offset=0;const load=async()=>{try{const result=await api('/api/product-records?offset='+offset+'&licenseId='+encodeURIComponent($('#modal-body [name=recordLicense]').value)+'&product='+encodeURIComponent($('#modal-body [name=recordProduct]').value));if(!$('#record-results'))return;$('#record-results').innerHTML=result.records.length?recordTable(result.records):empty('暂无记录','此筛选条件下尚无产品上报。');$('#record-page').textContent='共 '+result.total+' 条 · 第 '+(offset/100+1)+' 页';$('#record-prev').disabled=offset===0;$('#record-next').disabled=offset+100>=result.total;}catch(e){toast(e.message);}};$('#record-prev').onclick=()=>{offset=Math.max(0,offset-100);load();};$('#record-next').onclick=()=>{offset+=100;load();};$('#modal-body [name=recordLicense]').onchange=$('#modal-body [name=recordProduct]').onchange=()=>{offset=0;load();};load();}
function jobs(){return heading('云端打包','选择已发布的源码和主题，将任务交给匹配的打包节点。',`<button class="button primary" data-action="build">＋ 创建云端打包</button>`)+(!data.nodes.some(n=>n.status==='active'&&Date.parse(n.lastSeenAt)>Date.now()-300000)?'<div class="notice">当前没有在线打包节点。新任务将等待节点接入；不会自动生成安装包。</div>':'')+`<section class="panel">${data.jobs.length?table(['应用 / 版本','目标 / 引擎','创建者','创建时间','状态','操作'],data.jobs.map(j=>`<tr><td class="table-title">${E(j.app.name)}<div class="sub">v${E(j.app.version)} · ${E(j.app.packageId)}</div></td><td>${E(j.target)}<div class="sub">${E(j.engine)}</div></td><td>${E(licenseName(j.owner))}</td><td>${date(j.createdAt)}</td><td>${badge(j.status)}</td><td><div class="actions">${button('job-detail','日志',j.id)}${['queued','running'].includes(j.status)?button('cancel-job','取消',j.id):''}${j.status==='complete'?`<a class="button small" href="/api/jobs/${j.id}/artifact">下载成品</a>`:''}</div></td></tr>`)):empty('尚无云端打包','先上传客户端源码与主题，再创建应用云端打包。',button('build','创建任务'))}</section>`;}
function nodes(){return heading('打包节点','登记独立的 Android、iOS、Windows 或网页构建执行器。',`<button class="button primary" data-action="node">＋ 登记节点</button>`)+`<section class="panel">${data.nodes.length?table(['节点名称','支持目标','最近心跳','连接状态','状态','操作'],data.nodes.map(n=>`<tr><td class="table-title">${E(n.name)}</td><td>${n.targets.map(t=>`<span class="badge">${t}</span>`).join(' ')}</td><td>${date(n.lastSeenAt)}</td><td>${n.lastSeenAt?(Date.parse(n.lastSeenAt)>Date.now()-300000?'在线':'离线'):'尚未接入'}</td><td>${badge(n.status)}</td><td>${button('node-toggle',n.status==='active'?'停用':'启用',n.id)}</td></tr>`)):empty('没有打包节点','登记后，在构建执行器配置中填入终端地址与一次性节点令牌。',button('node','登记节点'))}</section><div class="notice subtle">Linux 终端负责调度和分发。iOS 原生编译需要配置 macOS / Xcode 节点及签名凭据，节点程序将在客户端集成阶段接入。</div>`;}
function audit(){return heading('操作记录','查看授权、版本发布与构建管理的最近 100 条关键操作。')+`<section class="panel">${data.audit.length?table(['操作','对象标识','时间'],data.audit.map(a=>`<tr><td class="table-title">${E(a.action)}</td><td class="code">${E(a.target)}</td><td>${date(a.at)}</td></tr>`)):empty('暂无操作记录','后续操作会自动记录在这里。')}</section>`;}
function integrations(){const info=data.integration;return heading('产品对接','统一服务地址、签名信任和三个产品的真实连接记录。',button('export-config','下载对接配置','','primary'))+panel('服务自检','当前服务器的授权签名与接口',`<div class="stat-line"><span>签名密钥</span><strong>${info.signatureValid?'自检通过':'自检失败'}</strong></div><div class="stat-line"><span>签名身份</span><span class="code">${E(info.keyId)}</span></div><div class="pre">${E(info.origin)}</div>`)+`<div class="integration-grid">${info.products.map(p=>panel(products[p.product],'真实记录，不以页面演示作为已对接',`<div class="stat-line"><span>累计激活绑定</span><strong>${p.bindings}</strong></div><div class="stat-line"><span>最近成功校验</span><span>${date(p.lastSeenAt)}</span></div><div class="stat-line"><span>已发布软件版本</span><strong>${p.publishedVersions}</strong></div><p class="section-note">${p.lastSeenAt?'已经收到产品激活或校验请求。请结合设备与站点列表核对来源。':'尚未收到此产品的成功请求，客户端对接待完成。'}</p>`)).join('')}</div>`+panel('接口清单','产品首次激活和周期校验使用同一套授权协议',table(['用途','地址'],Object.entries(info.endpoints).map(([k,v])=>`<tr><td>${E({publicKey:'公钥查询',activate:'首次激活',check:'定期校验',updates:'检查更新'}[k])}</td><td class="code break">${E(info.origin+v)}</td></tr>`)))+panel('接入顺序','客户端需要实现以下步骤',`<ol class="guide-list"><li>内置终端地址和固定信任公钥。</li><li>首次联网激活，以设备或运营站点域名绑定授权。</li><li>验证签名、请求随机数、授权范围与有效期后缓存离线凭据。</li><li>按校验周期联网；更新文件下载后核对 SHA-256。</li></ol><p class="section-note">终端协议已提供。主题、打包、运营三个产品的客户端接入将在后续单独完成。</p>`);}
function deployment(){
  const m=data.migration,a=m.authority,active=['preparing','restored'].includes(a.phase);
  const labels={normal:'正常运营',preparing:'旧服务器迁移中',restored:'新服务器待验收',completed:'迁移已完成',cancelled:'迁移已取消'};
  const notices=m.bindings.filter(b=>b.notice),connected=notices.filter(b=>b.notice.status==='connected'),waiting=m.bindings.length-notices.length;
  return heading('部署与迁移','一个加密迁移包，保留客户授权、软件资源和签名身份。')+
    panel('迁移控制',active?'业务修改已冻结，已有有效授权可继续验证':'正常运营，可准备迁移',
      '<div class="migration-summary"><div><span>运行状态</span><strong>'+E(labels[a.phase])+'</strong></div><div><span>已收到通知</span><strong>'+notices.length+'</strong></div><div><span>已连接正式地址</span><strong>'+connected.length+'</strong></div><div><span>尚未确认</span><strong>'+waiting+'</strong></div></div>'+
      (active?'<p class="section-note">宽限截止：'+date(a.graceUntil)+'。宽限仍受授权有效期限制；已停用、已到期授权不能恢复。等待中的构建取消，运行中的构建须先完成。</p>':'')+
      '<div class="form-actions">'+(!active?button('migration-start','开始迁移','','primary'):button('migration-cancel','取消迁移'))+(a.phase==='restored'?button('migration-finish','验收完成 · 恢复运营','','primary'):'')+'</div><p class="section-note">三个产品尚未接入本次迁移通知协议。这里仅显示真实请求确认；尚未确认可能是离线或未接入，不代表迁移失败。</p>')+
    '<div class="settings-grid migration-grid">'+panel('授权地址下发','验证同一签名身份后才保存和下发',
      '<div class="stat-line"><span>当前访问地址</span><code>'+E(data.origin)+'</code></div><div class="stat-line"><span>正式授权地址</span><code>'+E(a.primary||'尚未设置，使用当前访问地址')+'</code></div><div class="stat-line"><span>备用地址</span><code>'+E(a.fallbacks.join('、')||'未设置')+'</code></div><div class="stat-line"><span>签名身份 / 配置版本</span><code>'+E(data.keyId)+' / '+a.revision+'</code></div><p class="section-note">新地址须为公网 HTTPS 域名，且已恢复原私钥。备用地址也需验证；客户端重新联网才能取得新地址。域名和证书未接通时不会显示绑定成功。</p>'+button('migration-address','验证并下发地址','','primary'))+
    panel('导出旧服务器','签名私钥自动加密放入迁移包，无需手动复制',
      '<p class="section-note">包含管理员账号、授权中心、绑定、三产品版本、主题与源码、安装包、任务记录及签名密钥。磁盘流式 AES-256-GCM 加密，整包最多 8 GiB；服务器须有足够临时磁盘空间。导出前建议开启迁移。</p>'+button('migration-export','导出加密迁移包','','primary'))+
    panel('导入新服务器',data.integration.emptyTarget?'空白服务器，可以检查并导入':'已有业务数据，禁止覆盖',
      '<p class="section-note">先检查内容再确认导入。只需一个迁移密码；成功后使用旧管理员密码登录。端口、部署路径、证书和新服务器配置单独生成，避免搬入旧机器设置。</p>'+(data.integration.emptyTarget?button('migration-import','选择迁移包','','primary'):'<span class="badge disabled">仅允许空白服务器</span>'))+
    panel('Linux 管理','服务器入口配置与授权地址下发分开处理',
      '<div class="pre">sudo hetun</div><div class="stat-line"><span>安装 / 更新</span><code>sudo hetun deploy</code></div><div class="stat-line"><span>域名与 HTTPS</span><code>sudo hetun domain</code></div><div class="stat-line"><span>诊断入口</span><code>sudo hetun doctor</code></div><p class="section-note">无域名可用 IP 和服务端口访问。若 80/443 被其他容器占用，需复用其反向代理入口；不能通过更换内部端口自动获得无端口 HTTPS 域名。</p>')+'</div>'+
    panel('迁移步骤','旧服务器保留到新服务器验证成功',
      '<ol class="guide-list"><li>旧服务器点击开始迁移，再导出加密包，保存迁移密码。</li><li>新服务器安装终端，设置初始管理员密码；导入迁移包后使用旧密码登录。</li><li>同域名搬家：把 DNS 指向新服务器并接通 HTTPS。更换域名：先接通新域名，保留旧域名和备用入口过渡。</li><li>在新服务器验证并下发正式授权地址，核对客户、授权、文件和签名身份。</li><li>新服务器点击验收完成；确认业务可用后停止旧终端，避免两端写入。</li></ol><p class="section-note">迁移包已包含原私钥，丢失原私钥会导致已有客户端无法识别新终端。请把加密包与密码分开保管。更换所有旧地址前，确保离线客户仍有可重新连接的入口。</p>')+
    panel('客户接收记录','仅记录已认证设备的实际请求',table(['客户 / 产品','设备或域名','通知状态','请求地址','确认时间'],m.bindings.map(b=>'<tr><td>'+E(licenseName(b.licenseId))+'<small>'+E(products[b.product])+'</small></td><td>'+E(b.binding)+'</td><td>'+E(b.notice?(b.notice.status==='connected'?'已连接正式地址':'已收到通知'):'尚未确认')+'</td><td>'+E(b.notice?.origin||'—')+'</td><td>'+date(b.notice?.at)+'</td></tr>')));
}
function migrationStart(){formModal('开始迁移',field('graceDays','维护宽限（天）','number','7','required min="1" max="30"')+field('message','客户维护通知','text','授权中心维护迁移中，本地有效授权可继续使用。','maxlength="500"')+'<p class="section-note">开始后冻结授权、发布和新构建；等待中的任务会取消。已有运行任务须先结束。已停用或到期授权不受宽限保护。</p>','开启迁移',async v=>{await api('/api/migration/start','POST',{graceDays:Number(v.graceDays),message:v.message});$('#modal').close();await refresh();toast('迁移模式已开启');});}
function migrationAddress(){const a=data.migration.authority;formModal('验证并下发授权地址',field('primary','正式 HTTPS 地址','url',a.primary,'required placeholder="https://auth.example.com"')+field('fallbacks','备用地址，最多三个，逗号分隔','text',a.fallbacks.join(','))+'<p class="section-note">先在新服务器导入迁移包并接通域名和证书。终端会发随机挑战并验证原公钥签名，身份一致才下发。此操作不会修改 Cloudflare DNS。</p>','验证并保存',async v=>{await api('/api/migration/address','POST',{primary:v.primary,fallbacks:v.fallbacks.split(/[,，\n]/).map(x=>x.trim()).filter(Boolean)});$('#modal').close();await refresh();toast('身份验证通过，签名地址已下发');});}

function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportConfig(){downloadBlob(new Blob([JSON.stringify({schemaVersion:1,origin:data.origin,algorithm:'Ed25519',keyId:data.keyId,publicKey:data.publicKey,endpoints:data.integration.endpoints},null,2)],{type:'application/json'}),'hetun-integration.json');}
function migrationExport(){formModal('导出加密迁移包',field('current','当前管理员密码','password','','required')+field('passphrase','迁移密码','password','','required')+field('confirm','再次输入迁移密码','password','','required'),'加密并下载',async v=>{if(v.passphrase!==v.confirm)throw Error('两次迁移密码不一致');const r=await fetch('/api/migration/export',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({current:v.current,passphrase:v.passphrase})});if(!r.ok)throw Error((await r.json()).error);downloadBlob(await r.blob(),'puffer-'+new Date().toISOString().slice(0,10)+'.hetun');$('#modal').close();toast('迁移包已下载，请保存迁移密码');});}
function migrationImport(){formModal('检查迁移包',field('file','加密迁移文件','file','','required accept=".hetun"')+field('passphrase','迁移密码','password','','required'),'检查包内容',async(v,f)=>{const file=f.elements.file.files[0];const passphrase=btoa(Array.from(new TextEncoder().encode(v.passphrase),b=>String.fromCharCode(b)).join(''));const headers={'Content-Type':'application/octet-stream','X-Migration-Passphrase':passphrase};const result=await api('/api/migration/import','POST',file,headers),s=result.preview;formModal('确认迁移到此服务器',`<p class="section-note">将恢复旧管理员密码与签名身份，当前登录会退出。</p><div class="pre">来源：${E(s.sourceOrigin)}<br>导出时间：${date(s.createdAt)}<br>签名身份：${E(s.keyId)}<br>客户 ${s.customers} · 授权 ${s.licenses} · 绑定 ${s.bindings}<br>版本 ${s.releases} · 文件 ${s.files} · ${size(s.bytes)}</div><p class="section-note">请核对来源和签名身份，确认后导入。</p>`,'确认导入',async()=>{await api('/api/migration/import?confirm='+encodeURIComponent(s.keyId),'POST',file,headers);showLogin();toast('迁移成功，请使用旧服务器管理员密码登录');});});}

function updatePanel(){const s=data.selfUpdate||{},t=s.task||{};const names={queued:'等待执行',running:'正在更新',complete:'更新完成',failed:'更新失败'};return panel('版本与更新','河豚终端自身更新 · Git main 分支',`<div class="stat-line"><span>当前版本</span><strong>v${E(data.version)}</strong></div><div class="stat-line"><span>当前提交</span><span class="code">${E(s.currentRevision?.slice(0,12)||'本地工作区')}</span></div><div class="stat-line"><span>更新仓库</span><span>${E(s.repository)}</span></div>${s.latest?`<div class="stat-line"><span>Git 最新提交</span><span class="code">${E(s.latest.sha.slice(0,12))}</span></div><p class="section-note">${E(s.latest.message)}</p><p class="field-help">检查时间：${date(s.latest.checkedAt)} · ${s.currentRevision?(s.available?'发现新版本':'当前提交已与 Git 一致'):'本地修改尚未发布'}</p>`:''}<p class="section-note">${E(s.note||'')}</p>${t.state?`<div class="pre">${E(names[t.state]||t.state)}
${E(t.message||'')}${t.at?' · '+date(t.at):''}</div>`:''}<div class="form-actions">${button('terminal-check','检查 Git 更新')}<button class="button primary" data-action="terminal-update" ${!s.enabled||!s.available||['queued','running'].includes(t.state)?'disabled':''}>在线更新</button></div><p class="field-help">更新前自动备份；更新期间短暂重启。失败后尝试恢复上一版本，可在 Linux 菜单查看日志与备份。</p>`);}
function settings(){return heading('终端设置','管理授权周期、账户与客户端信任信息。')+`<div class="settings-grid">${policyPanel()}${panel('授权周期','应用离线凭据的统一策略',`<form id="settings-form"><div class="field-grid">${field('offlineDays','最长离线天数','number',data.settings.offlineDays,'min="1" max="30" required')}${field('checkHours','建议联网校验间隔（小时）','number',data.settings.checkHours,'min="1" max="720" required')}</div><p class="section-note">改变策略影响下一次签发的凭据。已签发的离线凭据保留原到期时间；联网时立即使用当前授权状态。</p><p class="error" id="settings-error"></p><div class="form-actions"><button class="button primary">保存策略</button></div></form>`)}${panel('管理员账户','密码只保存在服务器运行数据中',`<div class="stat-line"><span>登录账号</span><strong>admin</strong></div><div class="stat-line"><span>终端版本</span><strong>v${E(data.version)}</strong></div><div class="form-actions">${button('password','修改密码')}</div>`)}${panel('站点地址','客户端激活与更新服务地址',`<div class="pre">${E(data.origin)}</div><p class="section-note">修改域名请使用 Linux 菜单，更新反向代理与终端外部地址。域名或端口变更后，原有客户端配置需要同步。</p>`)}${panel('授权验证公钥','集成到产品中作为离线凭据的信任依据',`<div class="key-meta">Key ID：<span class="code">${E(data.keyId)}</span></div><pre class="pre">${E(data.publicKey)}</pre>${button('copy-public','复制公钥')}<p class="section-note">备份时必须同时保留私钥、授权数据与上传文件。产品应固定信任此公钥，不能每次联网都替换。</p>`)}</div>`;}
function render(){if(!data)return;$('#breadcrumb').textContent=pages[page];document.querySelectorAll('[data-page]').forEach(a=>a.classList.toggle('active',a.dataset.page===navSection(page)));$('#content').innerHTML=({overview,customers,bindings,releases:productCenter,products:productCenter,productTheme:productWorkspace,productPacker:productWorkspace,productOperations:productWorkspace,terminalUpdates:terminalWorkspace,updatePushes,announcements,jobs,nodes,integrations,deployment,audit,settings})[page]();$('#content').insertAdjacentHTML('afterbegin',sectionNavigation());const filter=$('#table-filter');if(filter)filter.addEventListener('input',()=>{const q=filter.value.toLowerCase(),groups=[...document.querySelectorAll('[data-customer-group]')];if(groups.length){for(const id of new Set(groups.map(tr=>tr.dataset.customerGroup))){const rows=groups.filter(tr=>tr.dataset.customerGroup===id),matches=rows.some(tr=>tr.textContent.toLowerCase().includes(q));rows.forEach(tr=>{tr.hidden=!matches;const detail=tr.querySelector('details');if(detail&&q&&matches)detail.open=true;});}}else document.querySelectorAll('tbody tr').forEach(tr=>tr.hidden=!tr.textContent.toLowerCase().includes(q));});const form=$('#settings-form');if(form)form.addEventListener('submit',async e=>{e.preventDefault();try{const v=Object.fromEntries(new FormData(form));await api('/api/settings','PATCH',{offlineDays:Number(v.offlineDays),checkHours:Number(v.checkHours)});await refresh();toast('授权策略已保存');}catch(err){$('#settings-error').textContent=err.message;}});}
function reveal(title,value){openModal(title,`<p class="section-note">请立即复制并妥善保存。关闭后无法再次查看；服务器只保存哈希。</p><div class="secret-value" id="secret-value">${E(value)}</div><div class="form-actions"><button class="button primary" id="copy-secret">复制并保存</button></div>`);$('#copy-secret').onclick=async()=>{try{await navigator.clipboard.writeText(value);toast('已复制，请保存到安全位置');}catch{toast('浏览器无法自动复制，请手动选择文本复制');}};}
const packageDuration=p=>p.durationUnit==='permanent'?'永久':p.duration+({days:'天',months:'个月',years:'年'}[p.durationUnit]||'');
function packagePanel(){const ps=data.authorizationPackages||[];return '<details class="panel license-section"><summary>授权套餐 · '+ps.length+' 个</summary><p class="field-help">自己设置产品、期限和模式。修改只影响以后签发的 Key；删除套餐保留已签发授权。</p>'+button('package-create','＋ 新增套餐','','primary')+(ps.length?table(['套餐','产品 / 模式','期限','操作'],ps.map(p=>'<tr><td>'+E(p.name)+'</td><td>'+E(p.products.map(x=>products[x]).join('、'))+'<div class="sub">'+E(p.authorizationMode?modeName(p.authorizationMode):'跟随全局')+'</div></td><td>'+E(packageDuration(p))+'</td><td>'+button('package-edit','编辑',p.id)+button('package-delete','删除',p.id,'danger')+'</td></tr>')):'')+'</details>';}
function packageEdit(id=''){const p=(data.authorizationPackages||[]).find(x=>x.id===id)||{products:['theme-center','packer','operations'],duration:1,durationUnit:'years',domainRule:'optional',quotas:{},permissions:{}};formModal(id?'编辑授权套餐':'新增授权套餐',field('name','套餐名字','text',p.name||'','required maxlength="80"')+'<div class="field-grid">'+field('duration','期限数量','number',p.duration||1,'min="1" max="36500"')+select('durationUnit','期限单位',[['days','天'],['months','月'],['years','年'],['permanent','永久']],p.durationUnit)+'</div>'+select('authorizationMode','授权模式',[['','跟随全局'],['online','在线管理'],['silent-local','静默本地']],p.authorizationMode||'')+'<h3>授权产品</h3>'+['theme-center','packer','operations'].map(x=>check('product-'+x,products[x],p.products.includes(x))).join('')+'<details class="license-section"><summary>域名、名额和权限</summary>'+select('domainRule','域名要求',[['optional','可留空'],['required','必须填写并绑定']],p.domainRule)+['theme-center','packer','operations'].map(x=>field('quota-'+x,products[x]+'名额','number',p.quotas[x]||(x==='operations'?1:2),'required min="1" max="100"')).join('')+['sourceDownload','localBuild','cloudBuild'].map(k=>check(k,{sourceDownload:'允许下载源码',localBuild:'允许本地打包',cloudBuild:'允许云端打包'}[k],p.permissions[k]!==false)).join('')+'</details>','保存套餐',async(v,f)=>{await api('/api/authorization-packages'+(id?'/'+id:''),id?'PATCH':'POST',{name:v.name,durationUnit:v.durationUnit,duration:Number(v.duration),authorizationMode:v.authorizationMode||null,domainRule:v.domainRule,products:['theme-center','packer','operations'].filter(x=>f.elements['product-'+x].checked),quotas:Object.fromEntries(['theme-center','packer','operations'].map(x=>[x,Number(v['quota-'+x])])),permissions:Object.fromEntries(['sourceDownload','localBuild','cloudBuild'].map(x=>[x,f.elements[x].checked]))});$('#modal').close();await refresh();toast('套餐已保存');});const f=$('#dialog-form');f.elements.durationUnit.onchange=()=>{f.elements.duration.disabled=f.elements.durationUnit.value==='permanent';};f.elements.durationUnit.onchange();}
function issue(){const ps=data.authorizationPackages||[];formModal('新增授权',field('label','名字','text','','required maxlength="80"')+'<label>授权域名（一行一个，可留空）<textarea name="domains" rows="2" placeholder="film.example.com"></textarea></label>'+select('packageId','授权套餐',[...ps.map(p=>[p.id,p.name+' · '+packageDuration(p)]),['','自定义授权']],ps[0]?.id||'')+'<p id="package-summary" class="field-help"></p><fieldset id="custom-grant" class="grant-fields">'+field('expiresAt','有效期','date',new Date(Date.now()+365*86400000).toISOString().slice(0,10),'required')+'<h3>授权产品</h3>'+['theme-center','packer','operations'].map(p=>check('product-'+p,products[p],true)).join('')+'<details class="license-section"><summary>高级设置</summary>'+select('authorizationMode','运行模式',[['','跟随全局'],['online','在线管理'],['silent-local','静默本地']],'')+['theme-center','packer','operations'].map(p=>field('quota-'+p,products[p]+'名额','number',p==='operations'?1:2,'required min="1" max="100"')).join('')+['sourceDownload','localBuild','cloudBuild'].map(k=>check(k,{sourceDownload:'允许下载源码',localBuild:'允许本地打包',cloudBuild:'允许云端打包'}[k],true)).join('')+'</details></fieldset>','生成 Key',async(v,f)=>{const payload={customer:{name:v.label,contact:''},label:v.label,domains:v.domains.split(/[\n,，]/).map(x=>x.trim()).filter(Boolean)};if(v.packageId){const p=ps.find(x=>x.id===v.packageId);Object.assign(payload,{packageId:p.id,packageRevision:p.revision});}else{Object.assign(payload,{expiresAt:new Date(v.expiresAt+'T23:59:59').toISOString(),products:['theme-center','packer','operations'].filter(x=>f.elements['product-'+x].checked),authorizationMode:v.authorizationMode||null,quotas:Object.fromEntries(['theme-center','packer','operations'].map(x=>[x,Number(v['quota-'+x])])),permissions:Object.fromEntries(['sourceDownload','localBuild','cloudBuild'].map(x=>[x,f.elements[x].checked]))});}const result=await api('/api/licenses','POST',payload);$('#modal').close();await refresh();reveal('授权 Key',result.key);});const f=$('#dialog-form');f.elements.packageId.onchange=()=>{const p=ps.find(x=>x.id===f.elements.packageId.value);$('#custom-grant').hidden=!!p;$('#custom-grant').disabled=!!p;$('#package-summary').textContent=p?p.products.map(x=>products[x]).join('、')+' · '+(p.authorizationMode?modeName(p.authorizationMode):'跟随全局')+' · '+(p.domainRule==='required'?'必须绑定域名':'域名可留空'):'';};f.elements.packageId.onchange();}
function releaseFields(isGit=false,asset=null){const info=centers[releaseProduct];return '<div class="field-grid">'+select('kind','资源类型',info.types.map(k=>[k,kinds[k]]),releaseTab)+'</div>'+field('name','版本名称','text',asset?.name||'','required maxlength="80"')+'<div class="field-grid">'+field('version','版本号','text',asset?.version||'1.0.0','required')+select('platform','平台',['windows','linux','android','ios','web','all'].map(x=>[x,x]),releaseProduct==='operations'?'linux':releaseProduct==='templates'?'all':releaseProduct==='client'?'android':'windows')+select('arch','架构',[['any','通用'],['x64','x64'],['arm64','arm64']])+select('channel','更新渠道',[['stable','正式'],['beta','测试']],asset?.channel||'stable')+select('engine','APP 源码引擎',[['none','不适用'],['flutter','Flutter'],['uniapp','uni-app']],releaseTab==='client-source'?'flutter':'none')+field('minVersion','最低允许版本','text','0.0.0','required')+'</div>'+check('force','强制更新',false)+'<label>更新说明<textarea name="notes" maxlength="5000" required>'+E(asset?.notes||'')+'</textarea></label>'+['installNotes','upgradeNotes','compatibility','sourceOrigin'].map(k=>'<label>'+{installNotes:'安装说明',upgradeNotes:'升级与数据处理说明',compatibility:'兼容要求（产品、主题、运行环境）',sourceOrigin:'源码 / 文件来源'}[k]+'<textarea name="'+k+'" maxlength="5000" rows="2"></textarea></label>').join('')+(isGit?'<p class="field-help">将下载并校验 Git Release 附件，保存为该产品的版本草稿。</p>':field('file','版本文件（最大 128 MB）','file','','required')+'<p class="field-help">产品源码为 ZIP；APP 源码与模板按其协议校验。运行数据和凭据不应包含在包内。</p>');}
function releaseMeta(v,form){const product=['templates','client'].includes(releaseProduct)?'client':releaseProduct;return {...v,product,force:form.elements.force.checked,engine:v.kind==='client-source'?v.engine:'none'};}
function upload(){formModal('上传 · '+centers[releaseProduct].title,releaseFields(),'上传并校验',async(v,form)=>{const file=form.elements.file.files[0];if(!file||file.size>128*1048576)throw Error('请选择不超过 128 MB 的文件');const meta={...releaseMeta(v,form),filename:file.name};delete meta.file;await api('/api/releases','POST',file,{'Content-Type':'application/octet-stream','X-Release-Metadata':encodeURIComponent(JSON.stringify(meta))});releaseTab=v.kind;$('#modal').close();await refresh();toast('已校验并保存草稿');});}
function importGit(assetId){const c=data.repositories?.[releaseProduct],r=c?.upstream?.find(x=>x.assets.some(a=>a.id===Number(assetId))),asset=r?.assets.find(a=>a.id===Number(assetId));if(!asset)throw Error('请重新检查 Git');formModal('Git 附件 · '+asset.name,releaseFields(true,{name:centers[releaseProduct].title+' '+r.tag,version:r.tag.replace(/^v/,''),notes:r.notes,channel:r.prerelease?'beta':'stable'}),'下载并校验',async(v,form)=>{await api('/api/repositories/'+releaseProduct+'/import','POST',{assetId:Number(assetId),metadata:releaseMeta(v,form)});releaseTab=v.kind;$('#modal').close();await refresh();toast('Git 附件已校验并进入草稿');});}
function build(){const sources=data.releases.filter(r=>r.kind==='client-source'&&r.status==='published'),themes=data.releases.filter(r=>r.kind==='theme'&&r.status==='published');if(!sources.length||!themes.length){toast('请先发布客户端源码和兼容的主题包');location.hash='releases';return;}formModal('创建云端打包',select('sourceId','客户端源码',sources.map(r=>[r.id,r.name+' / v'+r.version+' / '+r.engine]))+select('themeId','主题模板',themes.map(r=>[r.id,r.name+' / '+r.device]))+`<div class="field-grid">${select('target','构建目标',[['android','Android（手机 / 平板 / TV）'],['ios','iOS（手机 / 平板）'],['windows','Windows 桌面'],['web','网页']])}${field('name','应用名称','text','河豚影视','required maxlength="60"')}${field('version','应用版本','text','1.0.0','required')}${field('buildNumber','构建序号','number',1,'required min="1"')}</div>${field('packageId','应用包名','text','com.puffer.video','required')}${field('backend','运营后台 HTTPS 地址','url','','required placeholder="https://app.example.com"')}`,'加入构建队列',async v=>{await api('/api/jobs','POST',{...v,buildNumber:Number(v.buildNumber)});$('#modal').close();location.hash='jobs';await refresh();toast('任务已入队，等待匹配节点');});}
function node(){formModal('登记打包节点',field('name','节点名称','text','','required maxlength="80"')+'<label>支持的构建目标</label>'+['android','ios','windows','web'].map(t=>check('target-'+t,t,t==='android')).join('')+'<p class="section-note">登记节点不会安装编译工具。请在对应执行器配置地址与令牌，接入领取任务、心跳与产物回传接口。</p>','登记并生成令牌',async(v,f)=>{const targets=['android','ios','windows','web'].filter(t=>f.elements['target-'+t].checked);const result=await api('/api/nodes','POST',{name:v.name,targets});await refresh();reveal('节点令牌已生成',result.token);});}
function confirmation(title,description,action){formModal(title,`<p class="section-note">${E(description)}</p>`,'确认执行',async()=>{await action();$('#modal').close();await refresh();toast('操作已完成');});}
document.addEventListener('click',async e=>{const product=e.target.closest('[data-release-product]');if(product){releaseProduct=product.dataset.releaseProduct;releaseView='resources';render();return;}const view=e.target.closest('[data-release-view]');if(view){releaseView=view.dataset.releaseView;render();return;}const tab=e.target.closest('[data-release-tab]');if(tab){releaseTab=tab.dataset.releaseTab;render();return;}const b=e.target.closest('[data-action]');if(!b)return;const id=b.dataset.id,a=b.dataset.action;try{if(await communicationAction(a,id))return;if(a==='package-create')return packageEdit();if(a==='package-edit')return packageEdit(id);if(a==='package-delete')return confirmation('删除套餐','删除后不能再选择此套餐；已签发 Key 保持原授权。',()=>api('/api/authorization-packages/'+id,'DELETE'));if(a==='global-policy')return globalPolicy();if(a==='license-manage')return licenseManage(id);if(a==='authorization-logs')return authorizationLogs(id);if(a==='policy-distribution')return policyDistribution();if(a==='license-more')return licenseMore(id);if(a==='license-policy')return licenseManage(id);if(a==='software-push')return softwarePush(id);if(a==='software-update'){const p=workspaceProduct()||releaseProduct;b.disabled=true;b.textContent='正在更新…';try{const result=await api('/api/repositories/'+p+'/update','POST',{});await refresh();toast(result.message);}finally{b.disabled=false;b.textContent='更新';}return;}if(a==='git-config')return repositoryConfig();if(a==='git-import')return importGit(id);if(a==='record-browse')return recordBrowse();if(a==='git-check'){b.disabled=true;try{const result=await api('/api/repositories/'+releaseProduct+'/check','POST',{});await refresh();toast(result.error||'Git 更新与附件已检查');}finally{b.disabled=false;}return;}if(a==='terminal-check'){b.disabled=true;try{data.selfUpdate=await api('/api/self-update/check','POST',{});render();toast(data.selfUpdate.available?'发现 Git 新版本':'Git 检查完成');}finally{b.disabled=false;}return;}if(a==='terminal-update')return formModal('更新河豚终端','<p class="section-note">确认安装已检查的 Git 版本？将自动备份并重启终端，完成后重新登录。</p>','确认更新',async()=>{const task=await api('/api/self-update/install','POST',{revision:data.selfUpdate.latest.sha});data.selfUpdate.task=task;$('#modal').close();render();toast('更新已提交，可在此查看进度');});if(a==='export-config')return exportConfig();if(a==='migration-start')return migrationStart();if(a==='migration-address')return migrationAddress();if(a==='migration-cancel')return confirmation('取消迁移','恢复本机业务修改。已取消的构建不会自动恢复，请确认没有另一个终端同时运行。',()=>api('/api/migration/cancel','POST',{}));if(a==='migration-finish')return confirmation('完成迁移','请确认客户、授权、文件和正式地址均已核对。完成后恢复新服务器业务写入。',()=>api('/api/migration/finish','POST',{}));if(a==='migration-export')return migrationExport();if(a==='migration-import')return migrationImport();if(a==='customer')return issue();if(a==='issue')return issue(id);if(a==='upload')return upload();if(a==='build')return build();if(a==='node')return node();if(a==='password')return passwordModal();if(a==='copy-public'){await navigator.clipboard.writeText(data.publicKey);return toast('公钥已复制');}
if(a==='renew'){const l=data.licenses.find(x=>x.id===id);return formModal('续期授权',field('expiresAt','新的到期日期','date',l.expiresAt.slice(0,10),'required'),'保存续期',async v=>{await api('/api/licenses/'+id,'PATCH',{expiresAt:new Date(v.expiresAt+'T23:59:59').toISOString()});$('#modal').close();await refresh();toast('授权已续期');});}
if(a==='license-delete'){const l=data.licenses.find(x=>x.id===id);return confirmation('删除授权','确认删除客户「'+customer(l.customerId)+'」的「'+authorizationLabel(l)+'」？此 Key 的全部产品联网授权和设备绑定将失效，未完成构建会取消。客户资料和历史记录保留。已签发离线凭据仍可能使用至原到期时间。删除后无法直接恢复。',()=>api('/api/licenses/'+id,'DELETE'));}
if(a==='rotate')return formModal('轮换授权 Key','<p class="section-note">旧 Key 将立即失效，客户需要在产品中重新填入新 Key。已有离线凭据保留到原到期时间。</p>','生成新 Key',async()=>{const r=await api('/api/licenses/'+id+'/rotate','POST',{});await refresh();reveal('新授权 Key',r.key);});
if(['license-toggle','binding-toggle','node-toggle'].includes(a)){const collection=a.startsWith('license')?'licenses':a.startsWith('binding')?'bindings':'nodes',item=data[collection].find(x=>x.id===id),status=item.status==='active'?'disabled':'active';return confirmation(states[status]+(collection==='licenses'?'授权':collection==='bindings'?'绑定':'节点'),'此操作将改变后续联网请求的可用状态。',()=>api('/api/'+collection+'/'+id,'PATCH',{status}));}
if(['publish','withdraw'].includes(a))return confirmation(a==='publish'?'发布此版本':'下架此版本',a==='publish'?'发布后，已授权产品可以检查并下载此版本。':'下架后，产品目录不再展示此版本，已有云端打包不自动删除。',()=>api('/api/releases/'+id,'PATCH',{status:a==='publish'?'published':'withdrawn'}));
if(a==='cancel-job')return confirmation('取消云端打包','取消后，打包节点不能继续为此任务回传产物。',()=>api('/api/jobs/'+id+'/cancel','POST',{}));
if(a==='release-detail'){const r=data.releases.find(x=>x.id===id);return openModal('版本详情 · '+r.name,'<div class="key-meta">'+E(products[r.product]||r.product)+' · '+E(kinds[r.kind])+' · v'+E(r.version)+' · '+E(r.platform)+' / '+E(r.arch)+' · '+E(r.channel)+'</div><div class="stat-line"><span>文件</span><strong>'+E(r.filename)+' · '+size(r.bytes)+'</strong></div>'+[['更新说明',r.notes],['安装说明',r.installNotes],['升级说明',r.upgradeNotes],['兼容要求',r.compatibility],['源码 / 文件来源',r.gitSource?r.gitSource.repository+' @ '+r.gitSource.tag:r.sourceOrigin],['SHA-256',r.sha256],['创建时间',date(r.createdAt)],['发布时间',r.publishedAt?date(r.publishedAt):'尚未发布']].map(([t,v])=>'<h4>'+t+'</h4><pre class="pre release-text">'+E(v||'未填写')+'</pre>').join('')+'<p class="field-help">最低允许版本 '+E(r.minVersion)+' · '+(r.force?'强制更新':'普通更新')+'</p>');}
if(a==='job-detail'){const j=await api('/api/jobs/'+id);return openModal('构建日志 · '+j.app.name,`<div class="stat-line"><span>任务状态</span>${badge(j.status)}</div><div class="stat-line"><span>创建时间</span><span>${date(j.createdAt)}</span></div><pre class="pre">${E(j.logs.join('\n'))}${j.error?'\n\n'+E(j.error):''}</pre>${j.artifact?`<p class="field-help break">文件：${E(j.artifact.filename)}<br>SHA-256：${E(j.artifact.sha256)}</p>`:''}`);}
}catch(err){toast(err.message);}});

const noticeNames={message:'消息中心',banner:'顶部通知',popup:'弹窗公告',maintenance:'维护通知'};
function noticeState(n){if(n.status!=='published')return badge(n.status);if(n.endsAt&&Date.parse(n.endsAt)<=Date.now())return badge('expired');if(n.startsAt&&Date.parse(n.startsAt)>Date.now())return '<span class="badge">待生效</span>';return '<span class="badge active">生效中</span>';}
function deliverySummary(n){const r=data.deliveryReceipts.filter(x=>x.notificationId===n.id&&x.revision===n.revision);const count=s=>r.filter(x=>x.events.some(e=>e.status===s)).length;return '<strong>'+r.length+'</strong> 已反馈 · '+count('read')+' 已读'+(n.kind==='update'?' · '+count('installed')+' 安装成功':' · '+count('confirmed')+' 已确认');}
function communicationsPage(kind,productFilter='',hideCreate=false){const updates=kind==='update',items=(updates?data.updatePushes:data.announcements).filter(n=>!productFilter||n.products.includes(productFilter));return heading(updates?'更新推送':'公告中心',updates?'选择已发布的软件版本，指定接收产品、授权和生效时间。客户确认后安装，过程由产品回报。':'统一发布消息、顶部通知、弹窗和维护公告，记录产品实际接收与阅读反馈。',hideCreate?'':button(updates?'push-new':'notice-new',updates?'＋ 创建更新推送':'＋ 创建公告','','primary'))+'<div class="communications-panel">'+panel(updates?'软件推送计划':'公告列表',updates?'选择版本后推送给全部或指定授权，接收结果由产品实际回报。':'授权范围留空表示全部授权；发布数量不代表已送达。',items.length?table(['内容 / 产品','授权范围','有效时间','状态','接收反馈','操作'],items.map(n=>'<tr><td><span class="table-title">'+E(n.title)+'</span><div class="sub">'+E(n.products.map(p=>products[p]).join('、'))+' · '+E(updates?(data.releases.find(r=>r.id===n.releaseId)?.version||'版本不可用'):noticeNames[n.type])+'</div></td><td>'+E(n.licenseIds?.length?n.licenseIds.map(licenseName).join('、'):n.customerIds.length?n.customerIds.map(customer).join('、'):'全部授权')+'</td><td>'+date(n.startsAt).replace('未报告','发布后立即')+'<div class="sub">截止：'+(n.endsAt?date(n.endsAt):'不限定')+'</div></td><td>'+noticeState(n)+'</td><td>'+deliverySummary(n)+'</td><td><div class="actions">'+button('communication-detail','详情与记录',n.id)+(n.status==='draft'?button('communication-edit','编辑',n.id)+button('communication-publish','发布',n.id):'')+(n.status==='published'?button('communication-withdraw','撤回',n.id):'')+button('communication-copy','复制',n.id)+'</div></td></tr>')):empty(updates?'尚未创建推送':'尚未发布公告',updates?'点击更新获取成品版本，再选择授权推送。':'从草稿开始，选择展示方式与接收范围。'))+'</div>';}
function updatePushes(){return communicationsPage('update');}
function announcements(){return communicationsPage('announcement');}
function communicationFind(id){return [...data.announcements,...data.updatePushes].find(x=>x.id===id);}
function communicationEditor(kind,id='',copy=false){const updates=kind==='update',item=id?communicationFind(id):null;const scopedProduct=workspaceProduct();const initial=item||{products:scopedProduct?[scopedProduct]:(updates?['packer']:Object.keys(products).filter(p=>p!=='client')),customerIds:[]};const time=v=>v?new Date(Date.parse(v)-new Date(v).getTimezoneOffset()*60000).toISOString().slice(0,16):'';const available=data.releases.filter(r=>['software','installer'].includes(r.kind)&&r.status==='published'&&r.product!=='client'&&(!scopedProduct||item||r.product===scopedProduct));if(updates&&!available.length)return toast('请先在版本中心发布产品的软件安装包');const productFields=updates?select('product','接收产品',Object.entries(products).filter(([p])=>p!=='client'&&(!scopedProduct||item||p===scopedProduct)),initial.products[0]):'<fieldset class="notice-options"><legend>接收产品</legend>'+Object.entries(products).filter(([p])=>p!=='client').map(([p,t])=>'<label><input type="checkbox" name="products" value="'+p+'" '+(initial.products.includes(p)?'checked':'')+'>'+E(t)+'</label>').join('')+'</fieldset>';formModal(updates?'编辑更新推送':'编辑公告',field('title','标题','text',item?.title||'','required maxlength="120"')+productFields+(updates?select('releaseId','软件安装版本',available.map(r=>[r.id,products[r.product]+' · '+r.version+' · '+r.platform+' / '+r.arch]),item?.releaseId):select('type','展示方式',Object.entries(noticeNames),item?.type||'message')+select('releaseId','关联软件更新（可选）',[['','不关联'],...available.map(r=>[r.id,products[r.product]+' · '+r.version])],item?.releaseId||''))+'<label>正文 / 补充说明<textarea name="content" rows="5" maxlength="10000" '+(!updates?'required':'')+'>'+E(item?.content||'')+'</textarea></label><details class="notice-options"><summary>指定授权（不勾选表示全部授权）</summary>'+data.licenses.map(l=>'<label><input type="checkbox" name="licenseIds" value="'+E(l.id)+'" '+((initial.licenseIds?.includes(l.id)||(!initial.licenseIds?.length&&initial.customerIds?.includes(l.customerId)))?'checked':'')+'>'+E(authorizationLabel(l))+' · Key '+E(l.id.slice(0,8))+'</label>').join('')+'</details><div class="field-grid">'+field('startsAt','生效时间（可留空）','datetime-local',time(item?.startsAt))+field('endsAt','截止时间（可留空）','datetime-local',time(item?.endsAt))+'</div><label class="notice-check"><input type="checkbox" name="'+(updates?'force':'requireConfirmation')+'" '+((updates?item?.force:item?.requireConfirmation)?'checked':'')+'>'+(updates?'标记必须更新（需要客户端接入更新执行器）':'要求用户确认公告')+'</label><p class="section-note">保存为草稿，确认内容后另行发布。撤回后产品下一次联网检查会移除此通知。客户端需接入通知与更新执行器，并在任务空闲时安装。</p>','保存草稿',async(v,f)=>{const form=new FormData(f);const body={...v,products:updates?[v.product]:form.getAll('products'),customerIds:[],licenseIds:form.getAll('licenseIds'),startsAt:v.startsAt?new Date(v.startsAt).toISOString():null,endsAt:v.endsAt?new Date(v.endsAt).toISOString():null,force:form.has('force'),requireConfirmation:form.has('requireConfirmation')};const route=updates?'/api/update-pushes':'/api/announcements';await api(route+(id&&!copy?'/'+id:''),id&&!copy?'PATCH':'POST',body);$('#modal').close();await refresh();toast('草稿已保存');});if(updates){const updateOptions=()=>{const p=$('#dialog-form [name="product"]').value,el=$('#dialog-form [name="releaseId"]');el.innerHTML=available.filter(r=>r.product===p).map(r=>'<option value="'+E(r.id)+'">'+E(r.version+' · '+r.platform+' / '+r.arch+' · '+r.filename)+'</option>').join('');if(item?.releaseId&&available.some(r=>r.id===item.releaseId&&r.product===p))el.value=item.releaseId;};$('#dialog-form [name="product"]').onchange=updateOptions;updateOptions();}}
function communicationDetail(id){const n=communicationFind(id),receipts=data.deliveryReceipts.filter(r=>r.notificationId===id);const names={received:'已接收',read:'已读',confirmed:'已确认',downloaded:'已下载',installing:'正在安装',installed:'安装成功',failed:'失败'};openModal(n.title,'<div class="stat-line">'+noticeState(n)+'<span>通知修订 '+n.revision+'</span></div><pre class="pre release-text">'+E(n.content||data.releases.find(r=>r.id===n.releaseId)?.notes||'')+'</pre>'+table(['客户 / 产品','实际反馈','时间 / 说明'],receipts.map(r=>'<tr><td>'+E(customer(r.customerId))+'<div class="sub">'+E(products[r.product])+' · 修订 '+r.revision+'</div></td><td>'+E(names[r.status]||r.status)+'</td><td>'+date(r.updatedAt)+'<details><summary>反馈过程</summary>'+r.events.map(e=>'<p>'+E(names[e.status])+' · '+date(e.at)+' '+E(e.message)+'</p>').join('')+'</details></td></tr>'))+'<p class="section-note">此表仅显示客户端真实提交的反馈。未接入通知接口的旧客户端不会出现记录；安装成功需由更新后的程序启动并确认版本。</p>');}
async function communicationAction(action,id){if(action==='push-new'){softwarePush();return true;}if(action==='notice-new'){communicationEditor('announcement');return true;}if(!action.startsWith('communication-'))return false;const n=communicationFind(id),route=n.kind==='update'?'/api/update-pushes/':'/api/announcements/';if(action==='communication-edit'||action==='communication-copy')communicationEditor(n.kind,id,action==='communication-copy');if(action==='communication-detail')communicationDetail(id);if(action==='communication-publish')confirmation('发布通知','确认产品、客户范围及生效时间。产品下次联网检查后接收。',()=>api(route+id,'PATCH',{status:'published'}));if(action==='communication-withdraw')confirmation('撤回通知','撤回后停止后续推送，已有本地安装不会被撤销。',()=>api(route+id,'PATCH',{status:'withdrawn'}));return true;}


const workspaceRoutes={'theme-center':'productTheme',packer:'productPacker',operations:'productOperations'};
let workspaceTab='versions';const workspaceSelections={};
function workspaceProduct(){return Object.keys(workspaceRoutes).find(p=>workspaceRoutes[p]===page)||'';}
function navSection(p){if(['products','releases',...Object.values(workspaceRoutes)].includes(p))return 'products';if(p==='bindings')return 'customers';if(p==='announcements')return 'updatePushes';if(p==='nodes')return 'jobs';if(['settings','audit','deployment','integrations','terminalUpdates'].includes(p))return 'settings';return p;}
function sectionNavigation(){const groups={customers:[['customers','授权中心'],['bindings','设备与站点']],updatePushes:[['updatePushes','更新推送'],['announcements','公告管理']],jobs:[['jobs','云端打包'],['nodes','打包节点']],settings:[['settings','终端设置'],['terminalUpdates','终端更新'],['deployment','部署与迁移'],['integrations','产品对接'],['audit','操作记录']]};const items=groups[navSection(page)];return items?'<nav class="section-tabs" aria-label="管理分区">'+items.map(([p,t])=>'<a href="#'+p+'" class="tab '+(page===p?'active':'')+'">'+t+'</a>').join('')+'</nav>':'';}
function productCenter(){return heading('产品中心','三个产品独立管理，授权、版本与通知统一记录。')+'<div class="product-workspaces">'+Object.entries(workspaceRoutes).map(([p,route])=>{const software=data.releases.filter(r=>r.product===p&&['software','installer'].includes(r.kind)&&r.status==='published');const licenses=data.licenses.filter(l=>l.products.includes(p));const devices=data.bindings.filter(b=>b.product===p);const details={'theme-center':['主题创作与模板分发','管理主题软件、模板资源和创作记录。客户在主题中心编辑自己的项目。'],packer:['应用构建与安装包交付','管理打包软件、客户端源码和云端打包。编译由独立打包节点执行。'],operations:['APP 后台与站点授权','管理影视中心版本、域名授权和部署资料。内容运营由客户后台完成。']}[p];return '<a class="workspace-card" href="#'+route+'"><div class="workspace-card-top"><span class="workspace-symbol">'+centers[p].icon+'</span><span class="workspace-label">独立产品</span></div><h2>'+centers[p].title+'</h2><strong>'+details[0]+'</strong><p>'+details[1]+'</p><div class="workspace-metrics"><span><b>'+software.length+'</b>已发布软件版本</span><span><b>'+licenses.length+'</b>授权记录</span><span><b>'+devices.length+'</b>激活绑定</span></div><div class="workspace-enter">进入管理 <span>↗</span></div></a>';}).join('')+'</div>'+panel('管理职责','资源与业务各有归属','<div class="workspace-responsibilities"><div><strong>主题中心</strong><p>软件版本 · 模板库 · 创作记录</p></div><div><strong>打包器</strong><p>软件版本 · APP 源码 · 构建记录</p></div><div><strong>影视中心</strong><p>软件版本 · 域名授权 · 部署资料</p></div></div><p class="field-help">更新推送和公告在通知中心统一发布，也可进入对应产品查看。产品软件与主题模板分别发布、分别更新。</p>');}
function productLicenses(p){const licenses=data.licenses.filter(l=>l.products.includes(p));return panel('产品授权','当前产品包含在以下客户 Key 的授权范围中',licenses.length?table(['客户 / 授权','授权域名','到期时间','状态','操作'],licenses.map(l=>'<tr><td class="table-title">'+E(customer(l.customerId))+'<div class="sub">'+E(authorizationLabel(l))+'</div></td><td>'+E((l.domains||[]).join('、')||'未限定域名')+'</td><td>'+date(l.expiresAt)+'</td><td>'+badge(l.status==='active'&&Date.parse(l.expiresAt)<=Date.now()?'expired':l.status)+'</td><td>'+button('license-manage','管理统一授权',l.id)+'</td></tr>')):empty('暂无此产品授权','在授权中心中签发包含此产品的 Key。'),'<a class="button small" href="#customers">管理客户与 Key</a>')+'<p class="field-help">授权策略作用于该 Key 的全部授权产品。新增功能需要产品自身实现，再由终端发布对应软件版本。</p>';}

function softwareVersions(p){const config=data.repositories?.[p]||{};const items=data.releases.filter(r=>r.product===p&&['software','installer'].includes(r.kind));const groups=new Map();for(const r of items){const key=r.version+' / '+r.channel;const list=groups.get(key)||[];list.push(r);groups.set(key,list);}const list=[...groups.entries()].sort((a,b)=>Date.parse(b[1][0].createdAt)-Date.parse(a[1][0].createdAt));const current=list.find(([,rs])=>rs.some(r=>r.status==='published'));return panel('当前发布版本',config.repository?'已绑定 '+config.repository:'先绑定 Git 仓库，再一键更新',current?'<h2>v'+E(current[1][0].version)+'</h2><p class="release-text">'+E(current[1][0].notes)+'</p>':'<p class="muted">暂未发布成品安装包</p>','<div class="actions">'+button('software-update','更新','','primary')+button('software-push','推送')+button('git-config','产品设置')+'</div>')+'<p class="field-help">更新会下载并校验正式成品，自动发布。推送范围由你选择；只有源码提交时不会发布软件更新。</p>'+panel('版本记录','同一版本的安装文件合并显示',list.length?table(['版本','更新说明','状态 / 文件','操作'],list.map(([key,rs])=>'<tr><td><strong>v'+E(rs[0].version)+'</strong><div class="sub">'+E(rs[0].channel)+'</div></td><td>'+E(rs[0].notes)+'</td><td>'+rs.length+' 个文件 · '+rs.filter(r=>r.status==='published').length+' 个已发布</td><td>'+button('software-push','推送此版本',rs[0].version)+'<details><summary>文件与详情</summary>'+rs.map(r=>'<p>'+E(r.filename)+' · '+badge(r.status)+' '+button('release-detail','详情',r.id)+button(r.status==='published'?'withdraw':'publish',r.status==='published'?'下架':'发布',r.id)+' <a class="button small" href="/api/releases/'+r.id+'/download">下载</a></p>').join('')+'</details></td></tr>'),'software-version-table'):empty('暂无版本','点击更新获取正式成品，或展开手动上传。'))+'<details class="panel"><summary>手动上传与产品源码</summary>'+button('upload','上传文件')+table(['产品源码','版本','详情'],data.releases.filter(r=>r.product===p&&r.kind==='product-source').map(r=>'<tr><td>'+E(r.name)+'</td><td>'+E(r.version)+'</td><td>'+button('release-detail','详情',r.id)+button(r.status==='published'?'withdraw':'publish',r.status==='published'?'下架':'发布',r.id)+'</td></tr>'))+'</details>'+communicationsPage('update',p,true);}
function softwarePush(version='',selectedProduct=''){if(!workspaceProduct()&&!selectedProduct){formModal('选择推送产品','<label>产品<select name="product">'+Object.entries(products).filter(([id])=>id!=='client').map(([id,name])=>'<option value="'+E(id)+'">'+E(name)+'</option>').join('')+'</select></label>','下一步',async v=>{$('#modal').close();softwarePush(version,v.product);});return;}const p=selectedProduct||workspaceProduct();const available=data.releases.filter(r=>r.product===p&&r.status==='published'&&r.channel==='stable'&&['software','installer'].includes(r.kind)).sort((a,b)=>Date.parse(b.publishedAt)-Date.parse(a.publishedAt));if(!available.length)return toast('请先发布成品软件版本');const versions=[...new Set(available.map(r=>r.version))];const selected=version||versions[0];formModal('推送 '+products[p],select('version','推送版本',versions.map(v=>[v,'v'+v]),selected)+select('scope','接收范围',[['all','全部授权'],['selected','指定授权']],'all')+'<details open><summary>选择授权（仅“指定授权”时生效）</summary>'+data.licenses.filter(l=>l.products.includes(p)).map(l=>'<label class="notice-check"><input type="checkbox" name="licenseIds" value="'+E(l.id)+'">'+E(authorizationLabel(l))+' · Key '+E(l.id.slice(0,8))+'</label>').join('')+'</details>'+check('force','必须更新',false)+'<label>更新说明<textarea name="content" rows="4">'+E(available.find(r=>r.version===selected)?.notes||'')+'</textarea></label><p class="field-help">保存后立即推送。仅客户端实际回报后才显示接收、下载或安装结果。</p>','确认推送',async(v,f)=>{const ids=v.scope==='selected'?new FormData(f).getAll('licenseIds'):[];if(v.scope==='selected'&&!ids.length)throw Error('请选择至少一份授权');const result=await api('/api/update-pushes/send','POST',{product:p,version:v.version,title:products[p]+' v'+v.version,content:v.content,licenseIds:ids,customerIds:[],force:f.elements.force.checked});$('#modal').close();await refresh();toast('已推送 '+result.count+' 个版本文件');});const el=$('#dialog-form [name="version"]');el.onchange=()=>{$('#dialog-form [name="content"]').value=available.find(r=>r.version===el.value)?.notes||'';};}

function productWorkspace(){const p=workspaceProduct(),info=centers[p];workspaceTab=workspaceSelections[p]||'versions';const tabs=[['versions','软件版本'],...(p==='theme-center'?[['templates','主题模板']]:p==='packer'?[['client','APP 源码与成品'],['jobs','云端打包']]:[['sites','站点绑定'],['guide','部署说明']]),['licenses','产品授权'],['records','云端记录'],['update','更新推送'],['notice','产品公告']];if(!tabs.some(([t])=>t===workspaceTab))workspaceTab='versions';const tabsHTML='<nav class="workspace-tabs" aria-label="产品功能">'+tabs.map(([t,label])=>'<button class="tab '+(workspaceTab===t?'active':'')+'" data-workspace-tab="'+t+'">'+label+'</button>').join('')+'</nav>';let body='';if(workspaceTab==='versions'){releaseProduct=p;body=softwareVersions(p);}else if(['templates','client','records'].includes(workspaceTab)){releaseProduct=workspaceTab==='templates'?'templates':workspaceTab==='client'?'client':p;if(workspaceTab==='records')releaseView='records';else if(releaseView==='records')releaseView='resources';body=(workspaceTab==='records'?'':'<div class="workspace-resource-actions">'+button('upload','↑ 上传'+(workspaceTab==='templates'?'模板':workspaceTab==='client'?'APP 资源':'软件版本'),'','primary')+'</div>')+releases(true);}else if(workspaceTab==='licenses')body=productLicenses(p);else if(workspaceTab==='sites')body=bindings(p);else if(workspaceTab==='jobs')body=jobs();else if(workspaceTab==='update'||workspaceTab==='notice')body=communicationsPage(workspaceTab==='update'?'update':'announcement',p);else body=panel('影视中心安装与部署','部署在客户服务器，与苹果 CMS 保持独立业务职责','<ol class="deployment-steps"><li>上传并发布影视中心安装包，补充环境要求、安装说明与升级说明。</li><li>客户安装影视中心，使用授权 Key 激活并绑定后台域名。</li><li>在客户的影视中心配置苹果 CMS 连接与内容运营；终端管理授权和版本分发。</li><li>在更新推送中选择影视中心版本，追踪客户端回报的安装结果。</li></ol><p class="field-help">安装步骤与实际接口支持以发布包的版本详情为准。客户端自动接入仍需在对应产品完成。</p>','<button class="button small" data-workspace-tab="versions">查看安装版本</button>');return heading(info.title,info.text,'<a class="button" href="#products">返回产品中心</a>')+tabsHTML+'<div class="workspace-body">'+body+'</div>';}
function terminalWorkspace(){return heading('终端更新','管理河豚终端自身版本与 Git 在线更新。')+updatePanel();}
document.addEventListener('click',e=>{const tab=e.target.closest('[data-workspace-tab]');if(tab){workspaceTab=tab.dataset.workspaceTab;workspaceSelections[workspaceProduct()]=workspaceTab;releaseView='resources';render();}});

async function init(){try{const s=await api('/api/session');csrf=s.csrf;if(s.mustChange){showLogin();csrf=s.csrf;passwordModal(true);}else{showShell();await refresh();}}catch{showLogin();}}init();
setInterval(()=>{if(csrf&&data&&!$('#modal').open)refresh().catch(e=>{if(csrf)$('#refresh-state').textContent='连接中断，点击刷新';});},30000);

setInterval(async()=>{if(csrf&&data&&page==='settings'&&!$('#modal').open&&['queued','running'].includes(data.selfUpdate?.task?.state)){try{data.selfUpdate=await api('/api/self-update');render();}catch{if(csrf)$('#refresh-state').textContent='更新重启中，稍后刷新页面';}}},3000);

let authorizationLogView={licenseId:'',offset:0,filters:{},items:[]};
async function authorizationLogs(id='',offset=0){const v=authorizationLogView;if(v.licenseId!==id)v.filters={};v.licenseId=id;v.offset=offset;const f=v.filters,q=new URLSearchParams({...f,offset:String(offset)});if(!f.from&&f.period!=='all')q.set('from',new Date(Date.now()-7*86400000).toISOString());if(f.to)q.set('to',new Date(f.to+'T23:59:59.999').toISOString());if(id)q.set('licenseId',id);const result=await api('/api/authorization-logs?'+q);v.items=result.items;const names={activation:'首次激活',check:'启动 / 定期认证',denied:'授权拒绝','authorization-denied':'授权拒绝',reconnect:'重新连接','policy-received':'策略回执','offline-migration-import':'离线迁移导入','offline-migration-export':'离线迁移导出','theme-export':'主题导出','local-build':'本地打包','source-download':'源码下载','template-install':'模板安装','theme-install':'主题安装'},results={allowed:'通过',success:'成功',accepted:'通过',active:'有效',denied:'拒绝',failed:'失败',reported:'已补传'};openModal('授权日志'+(id?' · '+licenseName(id):' · 全部 Key'),'<p class="section-note">自动记录激活和认证，默认查看最近7天，保存 '+result.retentionDays+' 天。国家由 IP 推断；离线补传显示重连地点。已删除 Key 保留历史。</p><form id="authorization-log-filter" class="log-filter">'+select('period','时间范围',[['7','最近7天'],['all','全部保留记录']],f.period||'7')+select('product','产品',[['','全部产品'],...Object.entries(products).filter(([k])=>k!=='client')],f.product||'')+'<button class="button primary">筛选</button><details class="license-section"><summary>更多筛选</summary><div class="field-grid">'+field('deviceId','设备 ID','text',f.deviceId||'')+field('country','国家代码','text',f.country||'','maxlength="2" placeholder="如 CN"')+select('type','事件',[['','全部事件'],...Object.entries(names)],f.type||'')+field('from','开始日期','date',f.from||'')+field('to','结束日期','date',f.to||'')+'</div></details></form>'+table(['时间 / 事件','产品 / 版本','授权 / 设备','IP / 国家','结果'],result.items.map(x=>'<tr><td>'+E(date(x.occurredAt||x.receivedAt))+'<div class="sub">'+E(names[x.type]||x.type)+'</div><small>接收 '+E(date(x.receivedAt))+'</small></td><td>'+E(products[x.product]||x.product||'—')+'<div class="sub">'+E(x.version||'未报告')+'</div></td><td>'+E(x.licenseLabel||licenseName(x.licenseId))+'<div class="sub break">'+E(x.deviceId||'—')+'</div></td><td>'+E(x.ip||'未报告')+'<div class="sub">'+E(x.country||'未知')+(x.ipMeaning?' · 重连 IP':'')+'</div></td><td>'+E(results[x.result]||x.result||'—')+'</td></tr>'))+(result.items.length?'':'<p class="section-note">当前范围暂无日志，客户端激活或认证后自动出现。</p>')+'<div class="actions"><button id="auth-log-prev" class="button" '+(offset?'':'disabled')+'>上一页</button><span>'+(result.items.length?offset+1:0)+'–'+(offset+result.items.length)+' / '+result.total+'</span><button id="auth-log-next" class="button" '+(offset+100<result.total?'':'disabled')+'>下一页</button><button id="auth-log-export" class="button">导出当前页 CSV</button></div>');$('#authorization-log-filter').onsubmit=e=>{e.preventDefault();v.filters=Object.fromEntries([...new FormData(e.target)].filter(([,value])=>value));v.filters.country=(v.filters.country||'').toUpperCase();authorizationLogs(id,0).catch(e=>toast(e.message));};$('#auth-log-prev').onclick=()=>authorizationLogs(id,Math.max(0,offset-100)).catch(e=>toast(e.message));$('#auth-log-next').onclick=()=>authorizationLogs(id,offset+100).catch(e=>toast(e.message));$('#auth-log-export').onclick=()=>{const fields=['licenseId','product','version','deviceId','activationId','type','result','occurredAt','receivedAt','ip','country','geoSource','ipMeaning','parentDeviceId','policyRevision'];const cell=value=>'"'+String(value??'').replace(/^[=+@-]/,match=>"'"+match).replace(/"/g,'""')+'"';const text='\ufeff'+[fields.join(','),...v.items.map(x=>fields.map(k=>cell(x[k])).join(','))].join('\r\n');const url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='hetun-authorization-logs.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};}
async function policyDistribution(){const out=await api('/api/authorization-distribution');openModal('授权策略下发与回执','<p class="section-note">客户端成功联网取得策略后显示已获取；补传策略回执后显示已确认。</p><div class="table-wrap"><table><thead><tr><th>授权 / 产品</th><th>设备</th><th>最近连接</th><th>策略状态</th></tr></thead><tbody>'+out.devices.map(x=>'<tr><td>'+E(licenseName(x.licenseId))+'<br>'+E(products[x.product]||x.product)+'</td><td>'+E(x.deviceId)+'</td><td>'+E(date(x.lastSeenAt))+'</td><td>'+E(x.status==='disabled'?'绑定已停用':x.acknowledged?'已确认':x.received?'已获取，等待回执':'等待获取')+'</td></tr>').join('')+'</tbody></table></div>');}
